/// <summary>
/// Attribute class to decorate methods, that returns a dataset to be used when setting up the post prompt override.
/// </summary>
public class TFMOrderPostDataSetAttribute extends SysAttribute
{
    TableName tableName;
}

Method.Source:
/// <summary>
///    Retrieves the name of the dataset.
/// </summary>
/// <returns>
///    The name of dataset.
/// </returns>
public str name()
{
    return tableName;
}
